import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Extract configuration
  const { scenePosition = {}, imageUrl, cinematicPrimitives = [] } = config;
  const x = scenePosition.x ?? 0;
  const y = scenePosition.y ?? 0;
  const z = scenePosition.z ?? 0;
  const [rx, ry, rz] = scenePosition.rotationXYZ ?? [0, 0, 0];
  const [sx, sy, sz] = scenePosition.scaleXYZ ?? [1, 1, 1];

  // Load texture (cached by ctx.textureLoader)
  const texture = ctx.textureLoader.load(imageUrl || '/prism-mock/home/nodes/feature-card.png');

  // Create plane with 1.6:1 aspect ratio (512x320 atlas region)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Material for textured plane
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
    toneMapped: false,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene transform
  group.position.set(x, y, z);
  group.rotation.order = 'YXZ';
  group.rotation.set(rx, ry, rz);
  group.scale.set(sx, sy, sz);

  // Apply cinematic primitives (if specified)
  for (const primitive of cinematicPrimitives) {
    if (ctx.primitives && ctx.primitives[primitive.name]) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  }

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    gsap.killTweensOf(group);
  };

  // Event handlers
  group.userData.handlers = {};

  return group;
}
